import re

import sublime
import sublime_plugin

# {tag or {/tag, with optional type prefix ({data:items}), and the ~ of whitespace control
# just inside the brace ({~items~}, {~/items})
TAG_RE = re.compile(r'\{~?(/?)([A-Za-z_][A-Za-z0-9_]*(?::[A-Za-z_][A-Za-z0-9_]*)?)([^{}]*)')

# built-in tags that never take a closing tag - kept off the open-tag stack; the set is
# written by editors/generate.php, the list the other kits read from completions.json
# ---- generated by editors/generate.php from pad/ - do not edit by hand ----
SINGLE_TAGS = {
    'ajax', 'assert', 'asset', 'at', 'attrs', 'avatar', 'barcode', 'break',
    'calendar', 'cease', 'chess', 'classes', 'close', 'continue', 'countdown', 'country',
    'csrf', 'curl', 'debug', 'decrement', 'diff', 'dump', 'echo', 'emoji',
    'error', 'exception', 'excerpt', 'exit', 'extends', 'field', 'flush', 'foo',
    'get', 'gravatar', 'icon', 'identicon', 'img', 'increment', 'input', 'lorem',
    'meta', 'nonce', 'open', 'output', 'page', 'parent', 'parms', 'placeholder',
    'poll', 'progress', 'qr', 'rating', 'reactData', 'recurse', 'redirect', 'restart',
    'resume', 'set', 'source', 'sparkline', 'stack', 'sudoku', 'switch', 'textarea',
    'timeago', 'toc', 'trans', 'validator', 'video', 'vite',
}
# ---- end of generated ----

# the branch words of {if} and {case} divide a pair; they never open one of their own
BRANCH_TAGS = {'else', 'elseif', 'when'}

# the comments the engine drops before it scans - {# ... #}, not the option sigil {#name},
# and {-- ... --} - with any tag written inside them
COMMENT_RE = re.compile(r'\{#(?![A-Za-z_][A-Za-z0-9_]*\s*[}|])[\s\S]*?#\}|\{--\s[\s\S]*?--\}')


def open_tags(view, point):
    """Stack of PAD tags opened but not closed before point, innermost last."""
    text = COMMENT_RE.sub('', view.substr(sublime.Region(0, point)))
    stack = []
    for m in TAG_RE.finditer(text):
        closing, name = m.group(1), m.group(2)
        if closing:
            if name in stack:
                del stack[len(stack) - 1 - stack[::-1].index(name):]
        elif name not in SINGLE_TAGS and name not in BRANCH_TAGS and not m.group(3).rstrip('~').rstrip().endswith('/'):
            stack.append(name)
    return stack


class PadCloseTagCommand(sublime_plugin.TextCommand):
    """Insert the closing tag for the innermost open PAD tag.

    Falls back to Sublime's HTML close_tag when no PAD tag is open.
    """

    def run(self, edit):
        view = self.view
        point = view.sel()[0].b
        stack = open_tags(view, point)
        if stack:
            view.insert(edit, point, '{/' + stack[-1] + '}')
        else:
            view.run_command('close_tag')

    def is_enabled(self):
        return self.view.match_selector(0, 'text.html.pad')


class PadCloseTagListener(sublime_plugin.EventListener):
    """After typing {/ offer the currently open PAD tags as completions."""

    def on_query_completions(self, view, prefix, locations):
        point = locations[0] - len(prefix)
        if point < 2:
            return None
        if not view.match_selector(point, 'text.html.pad'):
            return None
        before = view.substr(sublime.Region(max(0, point - 3), point))
        if not before.endswith('{/') and before != '{~/':
            return None
        stack = open_tags(view, point - (3 if before == '{~/' else 2))
        if not stack:
            return None
        items = [
            sublime.CompletionItem(
                trigger=name,
                annotation='close tag',
                completion=name + '}',
                kind=(sublime.KIND_ID_MARKUP, '/', 'Close'),
            )
            for name in reversed(stack)
        ]
        return sublime.CompletionList(
            items,
            sublime.INHIBIT_WORD_COMPLETIONS | sublime.INHIBIT_EXPLICIT_COMPLETIONS,
        )
